<?= $this->extend('layout') ?>
<?= $this->section('content') ?>
<div class="page-head"><div><h1>Fleet and trips</h1></div><div class="actions"><?php if (can('fleet.manage')): ?><a class="btn" href="<?= site_url('fleet/trips/new') ?>">Plan a trip</a><a class="btn secondary" href="<?= site_url('fleet/vehicles/new') ?>">Add vehicle</a><a class="btn secondary" href="<?= site_url('fleet/drivers/new') ?>">Add driver</a><a class="btn secondary" href="<?= site_url('fleet/import') ?>">From Chatu Assets</a><?php endif ?><a class="btn secondary" href="<?= site_url('fleet/trips') ?>">All trips</a></div></div>
<?php if ($expiring): ?><section class="panel callout warn"><h2>Papers and services</h2><ul><?php foreach ($expiring as $e): ?><li class="<?= $e['overdue'] ? 'bad-text' : '' ?>"><a href="<?= site_url(ltrim($e['link'], '/')) ?>"><?= esc($e['what']) ?></a>: <?= esc($e['label']) ?><?= $e['date'] ? ' ' . nice_date($e['date']) . ' (' . esc(days_left($e['date'])) . ')' : ($e['overdue'] ? ' (none recorded)' : '') ?></li><?php endforeach ?></ul></section><?php endif ?>
<h2>Trips planned and on the road</h2>
<?php if (! $trips): ?><div class="panel empty">No trips planned.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Trip</th><th>Date</th><th>From</th><th>Vehicle</th><th>Driver</th><th class="num">Stops</th><th>Status</th></tr></thead><tbody>
<?php foreach ($trips as $t): ?><tr><td><a href="<?= site_url('fleet/trips/' . $t['id']) ?>"><?= esc($t['number']) ?></a></td><td><?= nice_date($t['planned_date']) ?></td><td><?= esc($t['wh']) ?></td><td><?= esc($t['reg_no']) ?></td><td><?= esc($t['driver']) ?></td><td class="num"><?= (int) $t['stops'] ?></td><td><?= badge($t['status']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<div class="cols"><section><h2>Vehicles</h2><div class="table-wrap"><table><thead><tr><th>Registration</th><th>Vehicle</th><th class="num">Carries</th><th class="num">Km</th><th>Status</th></tr></thead><tbody>
<?php foreach ($vehicles as $v): ?><tr><td><a href="<?= site_url('fleet/vehicles/' . $v['id']) ?>"><?= esc($v['reg_no']) ?></a></td><td><?= esc(trim($v['make'] . ' ' . $v['model'])) ?> <span class="muted small"><?= esc($v['body']) ?><?= $v['ownership'] !== 'own' ? ', ' . esc($v['ownership']) : '' ?></span></td><td class="num"><?= $v['capacity_kg'] ? number_format((float) $v['capacity_kg']) . ' kg' : '' ?></td><td class="num"><?= number_format((int) $v['odometer_km']) ?></td><td><?= badge($v['status']) ?><?= $v['trip'] ? ' ' . esc($v['trip']) : '' ?></td></tr><?php endforeach ?></tbody></table></div></section>
<section><h2>Drivers</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Phone</th><th>Licence</th><th>Expires</th></tr></thead><tbody>
<?php foreach ($drivers as $d): ?><tr class="<?= $d['status'] === 'active' ? '' : 'muted' ?>"><td><a href="<?= site_url('fleet/drivers/' . $d['id']) ?>"><?= esc($d['name']) ?></a><?= $d['trip'] ? ' <span class="badge warn">' . esc($d['trip']) . '</span>' : '' ?></td><td><?= esc($d['phone']) ?></td><td><?= esc(trim($d['licence_no'] . ' ' . $d['licence_class'])) ?></td><td class="<?= ! $d['licence_expiry'] || $d['licence_expiry'] < date('Y-m-d') ? 'bad-text' : '' ?>"><?= nice_date($d['licence_expiry']) ?: 'not recorded' ?></td></tr><?php endforeach ?></tbody></table></div></section></div>
<?= $this->endSection() ?>
